{"path": "outputs/t07_query.sparql", "content": "PREFIX wikibase: <https://www.wikidata.org/wiki/Property:P2254>
PREFIX wdt: <https://www.wikidata.org/prop/direct/>

SELECT ?item ?itemLabel ?itemLatitude ?itemLongitude
WHERE {
  ?item wdt:P31 wd:Q43229.
  ?item wdt:P625 ?itemGeo.
  ?item wdt:P17 wd:Q29.
  BIND(ST_AsText(?itemGeo) AS ?itemGeoText).
  FILTER (CONTAINS(?itemGeoText, "37.1692"))
  SERVICE wikibase:localEntityLookup {
    bd service#samples ?item ?itemLabel.
  }
}"}

